package com.projectdark.mobile;
import static org.junit.Assert.*;
import android.graphics.*;
import com.projectdark.mobile.world.*;
import java.util.*;
import java.io.*;
import java.lang.reflect.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class CountessCastleNativeV273Test {
 final MobileHudV134Test h=new MobileHudV134Test();
 @Before public void setup(){h.setup();}
 Object call(GameView v,String name,Class<?>[] types,Object...args)throws Exception{Method m=GameView.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(v,args);}
 void map(GameView v,String id)throws Exception{call(v,"changeCampaignMap",new Class<?>[]{String.class,boolean.class},id,false);}
 GameView view(int w,int height)throws Exception{GameView v=new GameView(h.c,false,true);v.layout(0,0,w,height);call(v,"travelTown",new Class<?>[]{String.class},DeathVillageGeometry.LOBBY);return v;}
 void shot(GameView v,String name,int width,int height)throws Exception{Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File f=new File("build/reports/countess-v273/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream o=new FileOutputStream(f)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,o));}assertNotEquals(b.getPixel(0,0),b.getPixel(width/2,height/2));b.recycle();}
 void npc(GameView v,String id)throws Exception{RuntimeState s=h.field(v,"state");RuntimeState.Npc n=s.npcs().stream().filter(a->id.equals(a.id)).findFirst().get();WorldRuntimeAdapter w=h.field(v,"poteFieldAdapter");assertTrue("NPC reachable through live collision "+id,CampaignNavigationTest.walk(w,w.requestNpcApproach(id)));w.snapCameraToPlayer();WorldCameraTransform.Point p=w.worldToScreen(n.x,n.y-25);EquipmentHudV262Test.tap(v,p.x,p.y);InteractionController interaction=h.field(v,"interaction");for(int i=0;i<40&&!interaction.dialogOpen();i++)call(v,"update",new Class<?>[]{float.class},.05f);assertTrue("real NPC touch "+id,interaction.dialogOpen());assertEquals(id,interaction.dialogNpc().id);assertEquals(CountessCastleTravel.GUARD.equals(id)?"백작부인별장입장":"백작부인의전령",interaction.dialogNpc().name);}
 @Test public void realGuardCancelConfirmAndExteriorEnvoyReachLobbyAndRestart()throws Exception{GameView v=view(960,540);RuntimeState s=h.field(v,"state");npc(v,CountessCastleTravel.GUARD);shot(v,"guard-dialogue",960,540);EquipmentHudV262Test.tap(v,670,425);assertEquals(DeathVillageGeometry.LOBBY,s.currentMapId());npc(v,CountessCastleTravel.GUARD);EquipmentHudV262Test.tap(v,550,425);assertEquals(CountessCastleGeometry.EXTERIOR,s.currentMapId());shot(v,"exterior",960,540);npc(v,CountessCastleTravel.ENVOY);EquipmentHudV262Test.tap(v,550,425);assertEquals(CountessCastleGeometry.LOBBY,s.currentMapId());assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(h.c);GameView restored=h.view();RuntimeState copy=h.field(restored,"state");assertEquals(CountessCastleGeometry.LOBBY,copy.currentMapId());shot(restored,"lobby-restored",960,540);}
 @Test public void allSixteenScenesRenderNativeArtAndHaveReachableLiveWorldPortalsInBothAspectRatios()throws Exception{for(int[] size:new int[][]{{960,540},{2340,1080}}){h.reset();GameView v=view(size[0],size[1]);for(String id:CountessCastleData.ids()){map(v,id);RuntimeState s=h.field(v,"state");WorldRuntimeAdapter w=h.field(v,"poteFieldAdapter");assertTrue(w.canPartyStandAt(s.player().x,s.player().y));shot(v,id+"-"+size[0],size[0],size[1]);if(size[0]==960){call(v,"openWorldMap",new Class<?>[]{});shot(v,id+"-overview",960,540);((WorldMapWindow)h.field(v,"worldMap")).close();}assertEquals(CountessCastleGeometry.gates(id).size(),WorldMapWindow.entrances(id).size());for(RuntimeState.Monster m:s.monsters()){m.alive=false;m.respawnClock=Float.POSITIVE_INFINITY;}for(CountessCastleGeometry.Gate g:CountessCastleGeometry.gates(id)){WorldMoveTargetController.TileCenter entry=CountessCastleGeometry.entry(id);s.player().x=entry.x;s.player().y=entry.y;w.cancelForAction();assertTrue("actual live navigation "+id+" to "+g.label,CampaignNavigationTest.walk(w,w.requestGroundWorld(g.x,g.y)));}}}}
 @Test public void allFourteenNativeSpeciesHaveFourDirectionsAndCompleteIdleWalkAttackWithExactVariantAlpha()throws Exception{CountessCastleRenderer r=new CountessCastleRenderer(h.c);Field f=CountessCastleRenderer.class.getDeclaredField("sheets");f.setAccessible(true);Set<Integer> seen=new HashSet<>();Bitmap review=Bitmap.createBitmap(4*240,14*190,Bitmap.Config.ARGB_8888);Canvas out=new Canvas(review);for(String id:CountessCastleData.ids()){r.prepare(id);Bitmap[][] sheets=(Bitmap[][])f.get(r);for(int t:CountessCastleMonsters.roster(id)){if(!seen.add(t))continue;Bitmap source=sheets[0][t];int[] a=new int[source.getWidth()*source.getHeight()];source.getPixels(a,0,source.getWidth(),0,0,source.getWidth(),source.getHeight());for(int v=1;v<4;v++){int[] b=new int[a.length];sheets[v][t].getPixels(b,0,source.getWidth(),0,0,source.getWidth(),source.getHeight());for(int k=0;k<a.length;k++)assertEquals(a[k]>>>24,b[k]>>>24);}int col=0;for(CharacterRenderer.Direction d:CharacterRenderer.Direction.values()){for(int pose=0;pose<3;pose++){RuntimeState.Monster m=new RuntimeState.Monster(CountessCastleMonsters.species(t)+"#pose","source",120,160,500000,"SOURCE");m.visualFacing.setLocomotion(d);m.isMoving=pose==1;m.animationClock=.25f;m.attackVisualRemaining=pose==2?.3f:0;Bitmap cell=Bitmap.createBitmap(240,190,Bitmap.Config.ARGB_8888);r.monster(new Canvas(cell),m,new SkillEffectState());int opaque=0;for(int y=0;y<190;y++)for(int x=0;x<240;x++)if(cell.getPixel(x,y)>>>24>0)opaque++;assertTrue("source pose "+t+" "+d+" "+pose,opaque>30);if(pose==2)out.drawBitmap(cell,col*240,t*190,null);cell.recycle();}col++;}}}assertEquals(14,seen.size());File dest=new File("build/reports/countess-v273/species-four-direction-attacks.png");dest.getParentFile().mkdirs();try(FileOutputStream o=new FileOutputStream(dest)){review.compress(Bitmap.CompressFormat.PNG,100,o);}review.recycle();r.release();assertEquals(0,r.atlasBytes());}
 @Test public void twelveRoundTripsRetainCurrentMapCacheBudgetsAndDoNotHealSavedEnemies()throws Exception{GameView v=view(960,540);List<Double> times=new ArrayList<>();Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);long maxAtlas=0;for(int trip=0;trip<12;trip++){String id=trip%2==0?CountessCastleGeometry.zoneId(3):CountessCastleGeometry.BOSS;map(v,id);RuntimeState s=h.field(v,"state");CountessCastleRenderer r=h.field(v,"countessRenderer");RuntimeState.Monster m=s.monsters().get(5);if(trip<2)s.damage(m,41);assertEquals(m.maxHp-41,m.hp);long start=System.nanoTime();v.draw(c);times.add((System.nanoTime()-start)/1e6);maxAtlas=Math.max(maxAtlas,r.atlasBytes());assertTrue(r.floorEntries()<=32);assertTrue(r.floorBytes()<=8652800);assertTrue("current-map atlas budget",r.atlasBytes()<=35389440);}System.out.println("V273_HOST_FRAME_MS="+times+" MAX_ATLAS_BYTES="+maxAtlas);b.recycle();call(v,"travelTown",new Class<?>[]{String.class},WorldDef.ID);CountessCastleRenderer r=h.field(v,"countessRenderer");assertEquals(0,r.atlasBytes());assertEquals(0,r.floorBytes());}
 @Test public void bossFirstDeathSecondLifeAndFinalDeathSurviveActualSaveRestartWithoutExtraRewards()throws Exception{GameView v=view(960,540);map(v,CountessCastleGeometry.BOSS);RuntimeState s=h.field(v,"state");RuntimeState.Monster first=s.monsters().get(0),second=s.monsters().get(1);s.damage(first,first.maxHp);s.tick(.01f);assertTrue(second.alive);assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(h.c);GameView next=h.view();RuntimeState copy=h.field(next,"state");assertFalse(copy.monsters().get(0).alive);assertTrue(copy.monsters().get(1).alive);copy.damage(copy.monsters().get(1),copy.monsters().get(1).maxHp);copy.tick(.01f);long exp=CampaignProgress.earnedExp(copy.rpg());assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(h.c);GameView last=h.view();RuntimeState restored=h.field(last,"state");assertFalse(restored.monsters().get(1).alive);restored.tick(20);assertFalse(restored.monsters().get(1).alive);assertEquals(exp,CampaignProgress.earnedExp(restored.rpg()));shot(last,"boss-final-restored",960,540);}
}
